function kthLuckyNumber(k) {
  // Skip whole lengths (there are 2^len lucky numbers of length len), then read the rank in base 2.
  let len = 1;
  let rank = k;
  while (rank > Math.pow(2, len)) {
    rank -= Math.pow(2, len);
    len++;
  }
  let index = rank - 1;
  const digits = [];
  for (let i = 0; i < len; i++) {
    digits.push(index % 2 === 0 ? '4' : '7');
    index = Math.floor(index / 2);
  }
  return digits.reverse().join('');
}

