function generate(rand, size) {
  if (size === 'small') return [1 + Math.floor(rand() * 300)];
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [1 + Math.floor(rand() * 1e9)];
  // Land near a length boundary: 2^(L+1) - 2 is the last lucky number of length L.
  const length = 20 + Math.floor(rand() * 9);
  const edge = Math.pow(2, length + 1) - 2;
  const k = edge + Math.floor(rand() * 5) - 2;
  return [Math.min(1e9, Math.max(1, k))];
}
